begin;
create function pg_temp.expect(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
create function pg_temp.rejects(statement text,label text) returns void language plpgsql as $$begin begin execute statement;exception when others then raise notice 'PASS: %',label;return;end;raise exception 'FAIL: %',label;end $$;
insert into auth.users(id) values('10000000-0000-0000-0000-000000000006'),('10000000-0000-0000-0000-000000000007');
insert into public.chat_profiles(id,display_name,role,must_change_password) values('10000000-0000-0000-0000-000000000006','Teacher','admin',false),('10000000-0000-0000-0000-000000000007','Student','student',false);
insert into public.chat_classes(id,name) values('20000000-0000-0000-0000-000000000003','Delete class'),('20000000-0000-0000-0000-000000000004','Keep class');
insert into public.chat_memberships(class_id,user_id) values('20000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000007'),('20000000-0000-0000-0000-000000000004','10000000-0000-0000-0000-000000000007');
insert into public.chat_messages(class_id,author_id,author_name,body,attachments) values('20000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000007','Student','photo','[{"kind":"image","path":"deleted-photo.jpg"}]');
insert into public.chat_messages(class_id,author_id,author_name,body,reply_to) select class_id,author_id,author_name,'reply',id from public.chat_messages where body='photo';
insert into public.chat_messages(class_id,author_id,author_name,body) values('20000000-0000-0000-0000-000000000004','10000000-0000-0000-0000-000000000007','Student','keep message');
select pg_temp.rejects($q$select public.chat_class_delete_preview('10000000-0000-0000-0000-000000000006','20000000-0000-0000-0000-000000000003')$q$,'teacher cannot preview class deletion');
select pg_temp.rejects($q$select public.chat_class_delete_execute('10000000-0000-0000-0000-000000000006','20000000-0000-0000-0000-000000000003','Delete class',2,1,0)$q$,'teacher cannot execute class deletion');
select pg_temp.expect((public.chat_class_delete_preview('10000000-0000-0000-0000-000000000009','20000000-0000-0000-0000-000000000003')->>'count')::int=2,'Owner preview includes messages');
select pg_temp.rejects($q$select public.chat_class_delete_execute('10000000-0000-0000-0000-000000000009','20000000-0000-0000-0000-000000000003','Wrong name',2,1,0)$q$,'stale class name denied');
select pg_temp.rejects($q$select public.chat_class_delete_execute('10000000-0000-0000-0000-000000000009','20000000-0000-0000-0000-000000000003','Delete class',3,1,0)$q$,'stale message count denied');
select pg_temp.rejects($q$select public.chat_class_delete_execute('10000000-0000-0000-0000-000000000009','20000000-0000-0000-0000-000000000003','Delete class',2,2,0)$q$,'stale membership count denied');
set local role authenticated;
select pg_temp.rejects($q$select public.chat_class_delete_execute('10000000-0000-0000-0000-000000000009','20000000-0000-0000-0000-000000000003','Delete class',2,1,0)$q$,'browser cannot call class delete RPC');
reset role;
select public.chat_class_delete_execute('10000000-0000-0000-0000-000000000009','20000000-0000-0000-0000-000000000003','Delete class',2,1,0);
select pg_temp.expect(not exists(select 1 from public.chat_classes where name='Delete class'),'selected class removed');
select pg_temp.expect(not exists(select 1 from public.chat_messages where body in('photo','reply')),'class messages and replies removed');
select pg_temp.expect(exists(select 1 from public.chat_media_gc where path='deleted-photo.jpg'),'media queued for physical cleanup');
select pg_temp.expect(exists(select 1 from auth.users where id='10000000-0000-0000-0000-000000000007') and exists(select 1 from public.chat_profiles where display_name='Student'),'student identity and profile preserved');
select pg_temp.expect((select count(*)=1 from public.chat_memberships),'only selected memberships removed');
select pg_temp.expect(exists(select 1 from public.chat_messages where body='keep message'),'other class history preserved');
select pg_temp.expect(exists(select 1 from public.chat_admin_audit where action='delete-class'),'deletion audited');
rollback;
